mapper.select:
select h.gym_id as gymId, h.item_category as itemCategory, h.item_name as itemName, sum(h.item_count) as itemCount, (select h2.item_price from "h_item" h2 where h2.gym_id = h.gym_id and h2.item_category = h.item_category and h2.item_name = h.item_name and h2.item_count > 0 order by h2.item_date desc, h2.item_id desc limit 1) as itemPrice from "h_item" h where h.gym_id=#{gymId}
and (h.item_name like concat('%', #{pager.searchKeyword}, '%') or h.item_category like concat('%', #{pager.searchKeyword}, '%'))
group by h.gym_id, h.item_category, h.item_name
order by itemCount desc order by itemCount asc order by itemPrice desc nulls last order by itemPrice asc nulls last order by h.item_name
limit #{pager.pageSize} offset #{pager.offset}

select count(*) from ( select 1 from "h_item" where gym_id=#{gymId}
and (item_name like concat('%', #{pager.searchKeyword}, '%') or item_category like concat('%', #{pager.searchKeyword}, '%'))
group by gym_id, item_category, item_name ) t

select gym_id as gymId, item_category as itemCategory, item_name as itemName, sum(item_count) as itemCount from "h_item" where gym_id=#{gymId}
and (item_name like concat('%', #{keyword}, '%') or item_category like concat('%', #{keyword}, '%'))
group by gym_id, item_category, item_name order by item_name

select * from "h_item"
where gym_id = #{gymId} and item_name = #{itemName}
order by item_date desc
